import{_ as i,l as o,o as a,c as l,v as t,p as d,x as r,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"顺序统计树","description":"","frontmatter":{"title":"顺序统计树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/order-statistic-tree.md","filePath":"cs/order-statistic-tree.md","lastUpdated":1789023840000}'),h={name:"cs/order-statistic-tree.md"};function m(k,e,_,u,S,T){const s=o("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="顺序统计树" tabindex="-1">顺序统计树 <a class="header-anchor" href="#顺序统计树" aria-label="Permalink to &quot;顺序统计树&quot;">​</a></h1><div class="epigraph"><p>每个节点多记一棵子树的规模，秩就是左子树大小加一；第 $k$ 小沿这条计数往下走。</p><footer>—— 据 Cormen, Leiserson, Rivest and Stein, Introduction to Algorithms 第 14 章；Sedgewick and Wayne 整理</footer></div><p><a href="/cs/splay-tree">上一课</a>与<a href="/cs/rbtree-intuition">红黑</a>、<a href="/cs/treap">Treap</a> 都给了有序字典，但合同只有按键。需要「第 \\(k\\) 小的键」或「小于 \\(x\\) 的有多少」。本课不重做 splay 势能。缺口是顺序统计树：在平衡 BST 上维护 <code>size</code>，<code>select</code>/<code>rank</code> 与增删同阶对数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有序数组 <code>select</code> 是下标，但插入 \\(\\Theta(n)\\)。只存 BST 没有规模就不能在比较路径上跳过「左边有多少」。缺口是字段 \\(\\mathrm{size}(u)=1+\\mathrm{size}(左)+\\mathrm{size}(右)\\)（空为 0）。\\(\\mathrm{rank}(x)\\)：走查找路径，往右走时加上左子树 size 再加一。\\(\\mathrm{select}(k)\\)：若 \\(k=\\mathrm{size}(左)+1\\) 则根，若更小则向左，否则向右减掉左边与根。</p><p>旋转、splay、treap 的 split 都必须更新 size，与维护平衡同一路径。</p><p><span class="marginnote">CLRS 第 14 章用红黑当底层。底层换成 AVL/Treap/Splay 只改维护点，不改秩的定义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>插入删除先当普通 BST 再修复平衡，回溯加/减 size，或旋转时按公式重算四个节点。区间 \\([L,R]\\) 内第 \\(k\\) 小：两个 rank 相减得左端前缀，再 select——这是应用，机制仍是全局序上的秩。</p>',9)),(a(),d(p,null,{default:r(()=>[c(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22select%20k%22%5D%20--%3E%20LSIZE%5B%22s%20%3D%20size(%E5%B7%A6)%22%5D%0A%20%20LSIZE%20--%3E%20EQ%5B%22k%20%3D%20s%2B1%3A%20%E6%A0%B9%22%5D%0A%20%20LSIZE%20--%3E%20LEFT%5B%22k%20%EF%BC%9C%3D%20s%3A%20%E5%B7%A6%22%5D%0A%20%20LSIZE%20--%3E%20RIGHT%5B%22k%20%3E%20s%2B1%3A%20%E5%8F%B3%2C%20k%20-%3D%20s%2B1%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与 Fenwick 权值树：值域离散且可映射到下标时，树状数组也能 rank/select。顺序统计树键任意可比较，不必整数化。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>平衡保证 \\(h=O(\\log n)\\)，故 rank/select 最坏或期望对数与底层一致。size 错一个节点，整棵秩全错——测试应查 <code>size</code> 与中序位置。多重键：size 计次数或拆节点，合同写明。</p><p>不要把「第 \\(k\\) 近邻几何」混进本课；那是后课 k-d 树。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写区间树的重叠查询。并发下 size 与旋转同锁。下一课把<a href="/cs/skip-list">跳表</a> 接到多线程：无根旋转，层指针 CAS。</p><p>后课默认：有序字典可以回答秩。共享内存里无锁有序集，先看并发跳表。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>顺序统计：BST + size，<code>rank</code>/<code>select</code> 对数。</li><li>旋转必须维护 size。</li><li>并发有序结构下一课走跳表，不旋根。</li><li>出处：Cormen et al. 第 14 章；Sedgewick and Wayne。</li></ul>',9))])}const B=i(h,[["render",m]]);export{A as __pageData,B as default};
